+    }
+
+    for(int cnt = 0; cnt < _allTaps.count(); cnt++)
+    {
+        _allTaps[cnt].setChecked(false);
+        if (_protocols.contains(_allTaps[cnt].protocol()))
+            _allTaps[cnt].setChecked(true);
+    }
+
